CREATE TYPE public.app_role AS ENUM ('admin');

CREATE TABLE public.admin_allowlist (created_at timestamptz DEFAULT now() NOT NULL, email text NOT NULL PRIMARY KEY CHECK (email = lower(email)), note text);
CREATE TABLE public.banners (accent text, active boolean DEFAULT true, btn_text text, category text, created_at timestamptz DEFAULT now(), description text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, link text, sort_order integer DEFAULT 0, subtitle text, title text, updated_at timestamptz DEFAULT now());
CREATE TABLE public.berita (active boolean DEFAULT true, author text, category text, content text, created_at timestamptz DEFAULT now(), event_date text, featured boolean DEFAULT false, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, location text, photo_source text, published_at timestamptz DEFAULT now(), slug text, source_name text, source_url text, status text, submitter_email text, submitter_name text, summary text, title text, updated_at timestamptz DEFAULT now());
CREATE TABLE public.community_applications (created_at timestamptz DEFAULT now() NOT NULL, email text NOT NULL, full_name text NOT NULL, hobby text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, interest text NOT NULL, origin_name text, origin_type text, reason text, whatsapp text NOT NULL);
CREATE TABLE public.digital_services (active boolean DEFAULT true, category text, created_at timestamptz DEFAULT now(), description text, featured boolean DEFAULT false, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, price numeric, title text, updated_at timestamptz DEFAULT now(), whatsapp text);
CREATE TABLE public.events (active boolean DEFAULT true, allow_voucher boolean DEFAULT false, banner_image text, category text, created_at timestamptz DEFAULT now(), crew_active boolean DEFAULT false, date text, date_end text, description text, featured boolean DEFAULT false, guest_stars jsonb, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, location text, maps_url text, menu_items jsonb, name text, organizer text, organizer_ig text, payment_info jsonb, price numeric, prohibited_items jsonb, rundown jsonb, service_fee_percent numeric, slug text, time_end text, time_start text, title text, transportation_info jsonb, updated_at timestamptz DEFAULT now(), visitors integer DEFAULT 0);
CREATE TABLE public.event_tickets (active boolean DEFAULT true, created_at timestamptz DEFAULT now(), description text, event_id bigint REFERENCES public.events(id) ON DELETE CASCADE, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text, price numeric, quota integer, sale_end text, sale_start text, sold integer DEFAULT 0, sort_order integer DEFAULT 0);
CREATE INDEX event_tickets_event_id_idx ON public.event_tickets (event_id);
CREATE TABLE public.influencers (active boolean DEFAULT true, bio text, color text, color2 text, created_at timestamptz DEFAULT now(), handle text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, instagram text, location text, name text, niches text[], photos text[], rate text, rating numeric, sort_order integer DEFAULT 0, tiktok text, updated_at timestamptz DEFAULT now(), verified boolean DEFAULT false);
CREATE TABLE public.kamus_sunda (active boolean DEFAULT true, category text, created_at timestamptz DEFAULT now(), example text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, indonesia text, latin text, level text, sunda text, updated_at timestamptz DEFAULT now());
CREATE TABLE public.kuliner (active boolean DEFAULT true, category text, created_at timestamptz DEFAULT now(), description text, facilities text, featured boolean DEFAULT false, google_maps_url text, hours text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, instagram text, location text, maps_embed_url text, name text, phone text, photos text, price_range text, rating numeric, reservasi_enabled boolean DEFAULT false, slug text, updated_at timestamptz DEFAULT now(), website text);
CREATE TABLE public.media_archive (id text PRIMARY KEY, manifest jsonb NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.partners (active boolean DEFAULT true, color text, created_at timestamptz DEFAULT now(), id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text, sort_order integer DEFAULT 0, updated_at timestamptz DEFAULT now());
CREATE TABLE public.partnership_proposals (brand_category text NOT NULL, brand_name text NOT NULL, budget_range text, collaboration_types text NOT NULL, contact_name text NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, email text NOT NULL, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, message text, status text DEFAULT 'diajukan' NOT NULL, whatsapp text NOT NULL);
CREATE TABLE public.penginapan (active boolean DEFAULT true, amenities text[], booking_enabled boolean DEFAULT false, category text, created_at timestamptz DEFAULT now(), description text, featured boolean DEFAULT false, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, instagram text, location text, name text, price_per_night numeric, rating numeric, slug text, updated_at timestamptz DEFAULT now());
CREATE TABLE public.perlombaan (active boolean DEFAULT true, category text, created_at timestamptz DEFAULT now(), date text, description text, featured boolean DEFAULT false, fee numeric, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, location text, max_peserta integer, name text, organizer text, prize numeric);
CREATE TABLE public.price_list (active boolean DEFAULT true, category text, created_at timestamptz DEFAULT now(), description text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, item text, price numeric, sort_order integer DEFAULT 0, updated_at timestamptz DEFAULT now());
CREATE TABLE public.promo_banners (active boolean DEFAULT true, created_at timestamptz DEFAULT now(), id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, link text, sort_order integer DEFAULT 0, updated_at timestamptz DEFAULT now());
CREATE TABLE public.site_settings (key text PRIMARY KEY, updated_at timestamptz DEFAULT now(), value text);
CREATE TABLE public.talents (active boolean DEFAULT true, bio text, category text, created_at timestamptz DEFAULT now(), featured boolean DEFAULT false, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, instagram text, name text, photo text, role text, sort_order integer DEFAULT 0, tagline text, tags text[], updated_at timestamptz DEFAULT now(), verified boolean DEFAULT false, wa text);
CREATE TABLE public.transportasi (active boolean DEFAULT true, asal text, created_at timestamptz DEFAULT now(), description text, frekuensi text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, jam text, kode text, name text, tarif numeric, tujuan text, type text, updated_at timestamptz DEFAULT now(), via text);
CREATE TABLE public.user_roles (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, role public.app_role NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, UNIQUE (user_id, role));
CREATE TABLE public.vouchers (active boolean DEFAULT true, applicable_type text, code text, created_at timestamptz DEFAULT now(), description text, discount_type text, discount_value numeric, expiry_date text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, kuliner_id bigint, min_purchase numeric, mitra_id bigint, required_points integer, title text, type text, updated_at timestamptz DEFAULT now());
CREATE TABLE public.wisata (active boolean DEFAULT true, category text, created_at timestamptz DEFAULT now(), description text, entry_fee numeric, facilities text, google_maps_url text, id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image text, instagram text, location text, maps_embed_url text, name text, opening_hours text, partner boolean DEFAULT false, phone text, photos text, rating numeric, slug text, updated_at timestamptz DEFAULT now(), website text);
CREATE TABLE public.yearbook_photo_submissions (caption text, created_at timestamptz DEFAULT now() NOT NULL, id uuid DEFAULT gen_random_uuid() PRIMARY KEY, mime_type text NOT NULL, sender_name text DEFAULT '' NOT NULL, status text DEFAULT 'pending' NOT NULL, storage_path text NOT NULL);

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['admin_allowlist','banners','berita','community_applications','digital_services','event_tickets','events','influencers','kamus_sunda','kuliner','media_archive','partners','partnership_proposals','penginapan','perlombaan','price_list','promo_banners','site_settings','talents','transportasi','user_roles','vouchers','wisata','yearbook_photo_submissions'] LOOP
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['banners','digital_services','event_tickets','events','influencers','kamus_sunda','kuliner','partners','penginapan','perlombaan','price_list','promo_banners','talents','transportasi','vouchers','wisata','berita'] LOOP
    EXECUTE format('GRANT SELECT ON public.%I TO anon', t);
  END LOOP;
END $$;
GRANT INSERT ON public.community_applications TO anon;
GRANT INSERT ON public.partnership_proposals TO anon;

CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.grant_allowlisted_admin()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.email_confirmed_at IS NOT NULL AND NEW.email IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.admin_allowlist WHERE email = lower(NEW.email)) THEN
    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'admin') ON CONFLICT (user_id, role) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE EXECUTE ON FUNCTION public.grant_allowlisted_admin() FROM PUBLIC, anon, authenticated;

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['admin_allowlist','banners','berita','digital_services','event_tickets','events','influencers','kamus_sunda','kuliner','media_archive','partners','partnership_proposals','penginapan','perlombaan','price_list','promo_banners','site_settings','talents','transportasi','user_roles','vouchers','wisata','yearbook_photo_submissions'] LOOP
    EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (public.has_role(auth.uid(), ''admin'')) WITH CHECK (public.has_role(auth.uid(), ''admin''))', 'Admins manage ' || t, t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['banners','digital_services','events','influencers','kamus_sunda','kuliner','partners','penginapan','perlombaan','price_list','promo_banners','talents','transportasi','vouchers','wisata'] LOOP
    EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO anon, authenticated USING (true)', 'Public can read ' || t, t);
  END LOOP;
END $$;
CREATE POLICY "Public can read berita" ON public.berita FOR SELECT TO anon USING (true);
CREATE POLICY "Public can read event_tickets" ON public.event_tickets FOR SELECT TO anon, authenticated USING (active IS TRUE AND EXISTS (SELECT 1 FROM public.events e WHERE e.id = event_tickets.event_id AND e.active IS TRUE));
CREATE POLICY "Users read own roles" ON public.user_roles FOR SELECT TO authenticated USING (auth.uid() = user_id OR public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete applications" ON public.community_applications FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins read applications" ON public.community_applications FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update applications" ON public.community_applications FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Anyone can apply" ON public.community_applications FOR INSERT TO anon, authenticated WITH CHECK ((char_length(btrim(full_name)) BETWEEN 3 AND 100) AND char_length(email) <= 255 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' AND (char_length(whatsapp) BETWEEN 9 AND 16) AND whatsapp ~ '^[0-9+[:space:]-]+$' AND interest = ANY (ARRAY['Designer','Web Developer','Content Creator','Videografer dan Fotographer','Marketing','Event Management']) AND origin_type IS NOT NULL AND origin_type = ANY (ARRAY['Sekolah','Kuliah','Umum']) AND char_length(COALESCE(origin_name,'')) <= 150 AND (origin_type = 'Umum' OR char_length(btrim(COALESCE(origin_name,''))) > 0) AND char_length(COALESCE(hobby,'')) <= 200 AND char_length(COALESCE(reason,'')) <= 1000);
CREATE POLICY "Anyone can propose a partnership" ON public.partnership_proposals FOR INSERT TO anon, authenticated WITH CHECK ((char_length(btrim(brand_name)) BETWEEN 2 AND 120) AND (char_length(btrim(contact_name)) BETWEEN 2 AND 100) AND char_length(email) <= 255 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' AND (char_length(whatsapp) BETWEEN 9 AND 16) AND whatsapp ~ '^[0-9+[:space:]-]+$' AND brand_category = ANY (ARRAY['Kuliner & F&B','Kopi & Cafe','Fashion & Apparel','Kosmetik & Perawatan','Ritel & UMKM','Teknologi & Aplikasi','Pendidikan & Sekolah','Instansi & Pemerintah','Media & Televisi','Lainnya']) AND (char_length(btrim(collaboration_types)) BETWEEN 2 AND 300) AND NOT EXISTS (SELECT 1 FROM unnest(string_to_array(collaboration_types, ',')) picked(item) WHERE btrim(picked.item) <> ALL (ARRAY['Sponsorship acara','Sponsorship produk','Booth & stand','Kerja sama konten','Media partner','Hadiah & doorprize','Lainnya'])) AND (budget_range IS NULL OR budget_range = ANY (ARRAY['Belum ditentukan','Barter produk / jasa','Di bawah Rp 5 juta','Rp 5 – 15 juta','Rp 15 – 30 juta','Di atas Rp 30 juta'])) AND char_length(COALESCE(message,'')) <= 1500 AND status = 'diajukan');

